type UserRow struct {
    ID   int64
    Name string
}

type UsersGateway struct{ db *sql.DB }

func (g *UsersGateway) Find(ctx context.Context, id int64) (UserRow, error) {
    var u UserRow
    err := g.db.QueryRowContext(ctx,
        "SELECT id, name FROM users WHERE id = $1", id).Scan(&u.ID, &u.Name)
    return u, err
}
